INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张浚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张浚。", "biography": null, "status": "draft", "id": "0ab7d6a4-deb7-5601-86cd-77e4e2b19fc2"}, {"name": "杨复恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：杨复恭。", "biography": null, "status": "draft", "id": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "李杰", "aliases": ["李敏", "唐昭宗"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：李杰。", "biography": null, "status": "draft", "id": "48935190-c754-5bda-bdcd-382c77cb2de0"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "杜让能", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杜让能。", "biography": null, "status": "draft", "id": "e3eae55f-2032-5c76-905f-e480ad32ea69"}, {"name": "刘崇望", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：刘崇望。", "biography": null, "status": "draft", "id": "ffc52aae-093c-57ce-a03c-f416683079f6"}, {"name": "孔纬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：孔纬。", "biography": null, "status": "draft", "id": "07254f47-15dc-55d0-b38f-bfefa4def94e"}, {"name": "孙揆", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：孙揆。", "biography": null, "status": "draft", "id": "528a2b41-d4fc-5590-8d17-224562470788"}, {"name": "韩建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“韩建出任司徒、同平章事”中为受任者。", "biography": null, "status": "draft", "id": "0a022fc7-47b3-5530-98ad-3625fceab9a5"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "李匡威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李匡威。", "biography": null, "status": "draft", "id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44"}, {"name": "赫连铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：赫连铎。", "biography": null, "status": "draft", "id": "b54a0fc9-ea29-5e0d-9d2a-f8fe5be8cda9"}, {"name": "牛徽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：牛徽。", "biography": null, "status": "draft", "id": "f9d7e691-03d4-5150-9590-3534d7cf5aad"}, {"name": "安居受", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：安居受。", "biography": null, "status": "draft", "id": "34293b35-c552-5b91-934b-a21194bc7738"}, {"name": "孟迁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：孟迁。", "biography": null, "status": "draft", "id": "b79a34bf-fa33-5615-b855-09c35628a57c"}, {"name": "李克恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见