ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "张浚与杨复恭旧隙的追叙", "start_year": null, "end_year": null, "time_original": "此前；具体年未载", "dynasty": "唐", "description": "《通鉴》追叙张浚原依杨复恭进身，杨复恭中废后改附田令孜，后与复用的杨复恭交恶；昭宗知两人有隙而亲倚张浚。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "54a4759a-e053-54df-a142-2663c7049374"}, {"title": "李克用评张浚，张浚闻而衔", "start_year": null, "end_year": null, "time_original": "讨黄巢及张浚作相前后；具体年日未载", "dynasty": "唐", "description": "《通鉴》追叙李克用讨黄巢屯河中时，张浚为都统判官；李克用后闻其为相，向诏使批评其虚谈无实用、会交乱天下，张浚听闻而记恨。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "70927701-b39e-569e-a2d9-98a8ff3fbd3a"}, {"title": "张浚主张强兵，昭宗募兵京师", "start_year": null, "end_year": null, "time_original": "昭宗与张浚论治乱时；具体年日未载", "dynasty": "唐", "description": "昭宗与张浚论治乱，张浚主张强兵以服天下，昭宗遂在京师广募兵，《通鉴》记至十万人。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4fdb0e5e-56db-578d-9eb1-00767b9a6fd6"}, {"title": "朝廷议讨河东，杜让能刘崇望反对", "start_year": 890, "end_year": 890, "time_original": "890年五月诏令前", "dynasty": "唐", "description": "昭宗命三省、御史台四品以上议讨李克用，书载六七成反对，杜让能、刘崇望亦反对。张浚主张借两河藩镇之势速讨，孔纬赞同，杨复恭认为不宜再启兵端；昭宗顾念李克用兴复之功，最终从张浚孔纬议。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "44becc47-e270-51a3-8a25-e7882766245c"}, {"title": "朝廷削夺李克用官爵属籍", "start_year": 890, "end_year": 890, "time_original": "890年五月", "dynasty": "唐", "description": "朝廷诏削夺李克用官爵、属籍。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "7aff23eb-8d8c-585d-bedc-6cb710085cd3"}, {"title": "张浚孙揆韩建获授河东行营职", "start_year": 890, "end_year": 890, "time_original": "890年五月", "dynasty": "唐", "description": "朝廷以张浚为河东行营都招讨制置宜慰使，孙揆副之，韩建为都虞候兼供军粮料使。", "phases": [], "location_name": "河东行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "255f7075-b68a-57cb-a562-19cd50a79b8d"}, {"title": "朱全忠王镕李匡威赫连铎获授分面招讨职", "start_year": 890, "end_year": 890, "time_original": "890年五月", "dynasty": "唐", "description": "朝廷以朱全忠为南面招讨使、王镕为东面招讨使、李匡威为北面招讨使、赫连铎为北面副使。", "phases": [], "location_name": "河东南面、东面、北面", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "be8f595e-d5e9-5eb0-8736-84e65270553a"}, {"title": "牛徽拒任河东行营判官", "start_year": 890, "end_year": 890, "time_original": "890年五月条；具体日未载", "dynasty": "唐", "description": "张浚奏请给事中牛徽为行营判官。牛徽认为国家经丧乱后不宜挑强寇、离诸侯心，以衰疾坚辞。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f6bf5e34-f8f4-56c1-9256-46bfc0ac5f87"}, {"title": "安居受等召河东兵取潞州的追叙", "start_year": null, "end_year": null, "time_original": "此前；具体年未载", "dynasty": "唐", "description": "《通鉴》追叙潞人反叛孟氏，牙将安居受等召河东军取得潞州。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e9cd2370-6f87-5820-80da-26ce6d6ece11"}, {"title": "孟迁受李克用宠任，引潞将怨惧", "start_year": 890, "end_year": 890, "time_original": "孟迁以三州归李克用后；具体日未载", "dynasty": "唐", "description": "孟迁以邢、洺、磁归李克用后，李克用宠任其为军城都虞候，其群从获补右职，安居受等怨惧。书中又述潞人怀念李克修简俭，对李克恭不满，军心离散。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e085946c-fcda-5f1b-894a-d05970318fcb"}, {"title": "李克用调昭义后院将赴晋阳", "start_year": 890, "end_year": 890, "time_original": "890年五月庚子前", "dynasty": "唐", "description": "李克用计划向河朔用兵，令李克恭选后院将中的骁勇者五百人赴晋阳；李克恭遣李元审、冯霸部送，潞人惜此精兵。", "phases": [], "location_name": "潞州、晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c4b3dd67-7589-51b2-8429-d08c53691700"}, {"title": "冯霸铜鞮劫众叛，李元审受伤", "start_year": 890, "end_year": 890, "time_original": "890年五月庚子前", "dynasty": "唐", "description": "冯霸至铜鞮劫众叛变，沿山向南至沁水，书载众至三千；李元审进击，受冯霸所伤，返回潞州。", "phases": [], "location_name": "铜鞮、沁水、潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e866ff51-d563-5812-8bcf-38418936391a"}, {"title": "安居受作乱焚杀李克恭李元审", "start_year": 890, "end_year": 890, "time_original": "890年五月庚子", "dynasty": "唐", "description": "李克恭赴李元审所住处探视，安居受率党作乱，攻击并纵火，李克恭、李元审皆死。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8756d55e-a1e6-5e1c-9467-32e542c05d90"}, {"title": "安居受被推留后归附朱全忠", "start_year": 890, "end_year": 890, "time_original": "890年五月庚子作乱后", "dynasty": "唐", "description": "众人推安居受为留后，归附朱全忠；安居受召冯霸，冯霸不来。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6aba028d-f54f-5925-aa2a-698de1b21160"}, {"title": "安居受出走被杀，冯霸自为留后", "start_year": 890, "end_year": 890, "time_original": "890年五月庚子条后；具体日未载", "dynasty": "唐", "description": "安居受害怕而出逃，为野人所杀；冯霸率军入潞州，自为留后。", "phases": [], "location_name": "潞州及出走途中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ac7c7428-f8ea-5c2a-8fec-1bdb55300266"}, {"title": "朱全忠遣朱崇节权知潞州留后", "start_year": 890, "end_year": 890, "time_original": "890年五月后条；李克恭死后", "dynasty": "唐", "description": "朝廷讨李克用时闻李克恭死，朝臣皆贺。朱全忠遣河阳留后朱崇节率兵入潞州，权知留后。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c4c50f8d-f4c4-5d2d-a772-8d730d8b6d50"}, {"title": "康君立李存孝围潞州", "start_year": 890, "end_year": 890, "time_original": "890年五月后条；朱崇节入潞州后", "dynasty": "唐", "description": "李克用遣康君立、李存孝率兵围攻潞州。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d604890f-2b66-5786-b4ea-548078b6366b"}]'::jsonb)
