SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "《通鉴》追叙张浚原依杨复恭进身，杨复恭中废后改附田令孜，后与复用的杨复恭交恶；昭宗知两人有隙而亲倚张浚。", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p017·原文件第48行", "note": "原文：初，张浚因杨复恭以进，复恭中废，更附田令孜而薄复恭。及复恭再用事，深恨之。上知浚与复恭有隙，特亲倚之。浚亦以功名为己任，每自比谢安、裴度。克用之讨黄巢屯河中也，浚为都统判官。克用薄其为人，闻其作相，私谓诏使曰：“张公好虚谈而无实用，倾覆之士也。主上采其名而用之，他日交乱天下，必是人也。”浚闻而衔。上从容与浚论古今治乱，浚曰：“陛下英睿如此，而中外制于强臣，此臣日夜所痛心疾首也。”上问以当今所急，对曰：“莫若强兵以服天下。”上于是广募兵于京师，至十万人。；核对说明：初与及复用为跨时追叙，不给890确年；不把阶段依附关系扩成永久主君。", "status": "draft", "id": "c31341cf-293c-5d78-a81e-8ac8b67c5cda", "subject_id": "54a4759a-e053-54df-a142-2663c7049374", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "此前；具体年未载", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p017·原文件第48行", "note": "原文：初，张浚因杨复恭以进，复恭中废，更附田令孜而薄复恭。及复恭再用事，深恨之。上知浚与复恭有隙，特亲倚之。浚亦以功名为己任，每自比谢安、裴度。克用之讨黄巢屯河中也，浚为都统判官。克用薄其为人，闻其作相，私谓诏使曰：“张公好虚谈而无实用，倾覆之士也。主上采其名而用之，他日交乱天下，必是人也。”浚闻而衔。上从容与浚论古今治乱，浚曰：“陛下英睿如此，而中外制于强臣，此臣日夜所痛心疾首也。”上问以当今所急，对曰：“莫若强兵以服天下。”上于是广募兵于京师，至十万人。；核对说明：初与及复用为跨时追叙，不给890确年；不把阶段依附关系扩成永久主君。", "status": "draft", "id": "f90044db-d4b0-51fe-bf9f-2a94ca3b33ed", "subject_id": "54a4759a-e053-54df-a142-2663c7049374", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记张浚：进身及改附者。", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p017·原文件第48行", "note": "原文：初，张浚因杨复恭以进，复恭中废，更附田令孜而薄复恭。及复恭再用事，深恨之。上知浚与复恭有隙，特亲倚之。浚亦以功名为己任，每自比谢安、裴度。克用之讨黄巢屯河中也，浚为都统判官。克用薄其为人，闻其作相，私谓诏使曰：“张公好虚谈而无实用，倾覆之士也。主上采其名而用之，他日交乱天下，必是人也。”浚闻而衔。上从容与浚论古今治乱，浚曰：“陛下英睿如此，而中外制于强臣，此臣日夜所痛心疾首也。”上问以当今所急，对曰：“莫若强兵以服天下。”上于是广募兵于京师，至十万人。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "06b9d510-5729-53b1-a37a-419b0f988bc1", "subject_id": "0ab7d6a4-deb7-5601-86cd-77e4e2b19fc2", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_t